import { createCipheriv } from "node:crypto";
import { beforeEach, afterEach, describe, it, expect, vi } from "vitest";
import { encryptToken, decryptToken, tokenKeyring } from "@/lib/crypto";
const owner = "11111111-1111-4111-8111-111111111111",
  other = "22222222-2222-4222-8222-222222222222";
export function legacyToken(value = "fixture-token") {
  const cipher = createCipheriv(
    "aes-256-gcm",
    Buffer.from("ab".repeat(32), "hex"),
    Buffer.alloc(12, 1),
  );
  const encrypted = Buffer.concat([cipher.update(value), cipher.final()]);
  return [
    "v1",
    Buffer.alloc(12, 1).toString("base64url"),
    cipher.getAuthTag().toString("base64url"),
    encrypted.toString("base64url"),
  ].join(".");
}
beforeEach(() => {
  vi.stubEnv("TOKEN_ENCRYPTION_KEY", "ab".repeat(32));
  vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY_ID", "A");
  vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY", "cd".repeat(32));
  vi.stubEnv("TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON", "{}");
});
afterEach(() => vi.unstubAllEnvs());
describe("owner authenticated token envelopes", () => {
  it("reads fixed legacy v1 envelopes and writes random v2 nonces", () => {
    expect(decryptToken(legacyToken(), owner)).toBe("fixture-token");
    const value = encryptToken("fixture-token", owner);
    expect(value.startsWith("v2.A.")).toBe(true);
    expect(decryptToken(value, owner)).toBe("fixture-token");
    expect(encryptToken("fixture-token", owner)).not.toBe(value);
  });
  it("rejects wrong owner, versions, unknown keys and every tampered component with constant errors", () => {
    const value = encryptToken("fixture-token", owner);
    expect(() => decryptToken(value, other)).toThrow("TOKEN_ENCRYPTION_FAILED");
    for (let i = 0; i < 5; i++) {
      const parts = value.split(".");
      parts[i] = i === 0 ? "v3" : i === 1 ? "unknown" : "AAAAAAAAAAAAAAAA";
      expect(() => decryptToken(parts.join("."), owner)).toThrow(
        "TOKEN_ENCRYPTION_FAILED",
      );
    }
    expect(() => decryptToken(value + ".extra", owner)).toThrow(
      "TOKEN_ENCRYPTION_FAILED",
    );
  });
  it("requires each referenced v2 key and never falls back to legacy", () => {
    const a = encryptToken("fixture-token", owner);
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY_ID", "B");
    vi.stubEnv("TOKEN_ENCRYPTION_ACTIVE_KEY", "ef".repeat(32));
    expect(() => decryptToken(a, owner)).toThrow("TOKEN_ENCRYPTION_FAILED");
    vi.stubEnv(
      "TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON",
      JSON.stringify({ A: "cd".repeat(32) }),
    );
    expect(decryptToken(a, owner)).toBe("fixture-token");
    expect(encryptToken("fixture-token", owner)).toMatch(/^v2.B\./);
  });
  it.each([
    "[]",
    "null",
    '{"A":"bad"}',
    JSON.stringify({ B: "bad" }),
    JSON.stringify({ "bad.id": "ab".repeat(32) }),
  ])("fails closed for invalid keyring %s", (json) => {
    vi.stubEnv("TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON", json);
    expect(() => tokenKeyring()).toThrow("TOKEN_ENCRYPTION_FAILED");
  });
});
